-- Analytical View: FOXA1 Mutation and Expression Summary---- Purpose:-- Provide descriptive expression statistics for FOXA1-- according to mutation status and histological subtype.---- Grain:-- One row per histological subtype and mutation status.---- Source:-- analytical.vw_foxa1_mutation_expressionCREATE OR REPLACE VIEW analytical.vw_foxa1_mutation_expression_summary ASSELECT    histological_type,    mutation_status,    COUNT(*) AS sample_count,    ROUND(        AVG(expression_level)::numeric,        4    ) AS mean_expression,    ROUND(        PERCENTILE_CONT(0.5)        WITHIN GROUP (ORDER BY expression_level)::numeric,        4    ) AS median_expression,    MIN(expression_level) AS min_expression,    MAX(expression_level) AS max_expressionFROM analytical.vw_foxa1_mutation_expressionGROUP BY    histological_type,    mutation_status;